import csv, re, json, collections
from decimal import Decimal
from datetime import date

RUN_DATE = date(2026,6,30)

def clean(s):
    return s.strip()

def parse_amount(s):
    s = clean(s).replace('$','').replace(',','')
    neg = False
    if s.startswith('(') and s.endswith(')'):
        neg = True
        s = s[1:-1]
    val = Decimal(s)
    return -val if neg else val

def parse_rate(s):
    return Decimal(clean(s))

def parse_date(s):
    return date.fromisoformat(clean(s))

# Load customer master
cust = {}
with open('input/customer_master.csv', newline='') as f:
    for r in csv.DictReader(f):
        cust[clean(r['customer_id']).lower()] = r

def end_user_type(cid):
    r = cust.get(clean(cid).lower())
    if not r:
        return 'UNKNOWN'
    ac = clean(r['account_class']).lower()
    if ac == 'house':
        return 'house'
    fid = parse_date(r['first_invoice_date'])
    if fid >= date(2025,7,1):
        return 'new'
    return 'renewal'

std_rate = {'new': Decimal('8'), 'renewal': Decimal('4'), 'house': Decimal('0')}

# Load exceptions
exc_rows = []
with open('input/commission_exceptions.csv', newline='') as f:
    for r in csv.DictReader(f):
        exc_rows.append(r)

def active_exception(deal_key):
    # deal_key lower
    applicable = []
    for r in exc_rows:
        if clean(r['deal_id']).lower() != deal_key:
            continue
        if clean(r['status']).lower() != 'active':
            continue
        if parse_date(r['effective_from']) <= RUN_DATE <= parse_date(r['effective_to']):
            applicable.append(r)
    return applicable[0] if applicable else None

# Load co-sell
co = collections.defaultdict(list)
with open('input/co_sell_register.csv', newline='') as f:
    for r in csv.DictReader(f):
        co[clean(r['deal_id']).lower()].append(r)

def co_sell_valid(deal_key, line_partners):
    rows = co.get(deal_key, [])
    if not rows:
        return False, {}
    if any(clean(r['status']).lower() != 'active' for r in rows):
        return False, {}
    reg_partners = sorted(clean(r['partner']).lower() for r in rows)
    line_partners_sorted = sorted(p.lower() for p in line_partners)
    if reg_partners != line_partners_sorted or len(rows) != len(line_partners):
        return False, {}
    shares = [Decimal(clean(r['share_pct'])) for r in rows]
    if sum(shares) != 100:
        return False, {}
    # map partner lower -> share
    return True, {clean(r['partner']).lower(): Decimal(clean(r['share_pct'])) for r in rows}

# Load ledger
ledger_rows = []
seen_post = set()
with open('input/netsuite_revenue_june.csv', newline='') as f:
    for r in csv.DictReader(f):
        pid = clean(r['posting_id'])
        if pid in seen_post:
            ledger_rows.append({**r, '_dup_posting': True})
            continue
        seen_post.add(pid)
        ledger_rows.append({**r, '_dup_posting': False})

# Identify reversals by memo reference
reversal_of = {}
for r in ledger_rows:
    m = re.search(r'(?:reversal of|credit note against)\\s+(P-\\d+)', r['memo'], re.I)
    if m:
        reversal_of[clean(r['posting_id'])] = m.group(1)

reversed_postings = set()
for rev_pid, orig_pid in reversal_of.items():
    reversed_postings.add(orig_pid)
    reversed_postings.add(rev_pid)  # the reversal row itself records nothing for customer

def is_june(d):
    return d.year == 2026 and d.month == 6

ledger_by_deal = collections.defaultdict(list)
for r in ledger_rows:
    ledger_by_deal[clean(r['deal_ref']).lower()].append(r)

def active_june_postings(deal_key):
    out = []
    for r in ledger_by_deal.get(deal_key, []):
        pid = clean(r['posting_id'])
        if pid in reversed_postings:
            continue
        if is_june(parse_date(r['posting_date'])):
            out.append(r)
    return out

def net_june_revenue(deal_key):
    total = Decimal(0)
    seen = set()
    for r in ledger_by_deal.get(deal_key, []):
        pid = clean(r['posting_id'])
        if pid in seen:
            continue
        seen.add(pid)
        if is_june(parse_date(r['posting_date'])):
            total += parse_amount(r['amount_usd'])
    return total

# Load commission lines, deduplicate by line_id
line_rows = []
with open('input/commission_lines.csv', newline='') as f:
    for r in csv.DictReader(f):
        line_rows.append(r)

lines_by_id = collections.OrderedDict()
conflicts = []
for r in line_rows:
    lid = clean(r['line_id'])
    if lid not in lines_by_id:
        lines_by_id[lid] = r
    else:
        # conflict check
        if r != lines_by_id[lid]:
            conflicts.append((lid, lines_by_id[lid], r))
lines = list(lines_by_id.values())

# group by deal
deal_lines = collections.defaultdict(list)
for r in lines:
    deal_lines[clean(r['deal_id']).lower()].append(r)

def line_partners_for_deal(deal_key):
    return [clean(r['source_report']) for r in deal_lines[deal_key]]

# Analysis
findings = []
compliant_off_standard = []
odd_compliant = []
notes = []
for r in lines:
    lid = clean(r['line_id'])
    deal = clean(r['deal_id'])
    deal_key = deal.lower()
    partner = clean(r['source_report'])
    partner_cid = clean(r['customer_id'])
    rev = parse_amount(r['revenue_usd'])
    reported_rate = parse_rate(r['reported_rate_pct'])

    # duplicate detection by unique line_id
    dup = len(deal_lines[deal_key]) > 1
    cosell_valid, shares = co_sell_valid(deal_key, line_partners_for_deal(deal_key))
    if dup and not cosell_valid:
        finding = 'DUPLICATE_LINE'
    else:
        # customer
        active_posts = active_june_postings(deal_key)
        if active_posts:
            # if multiple active June postings, use first? policy says customer NetSuite records against deal's June postings; for customer type, any? Need first or all same?
            ledger_cid = clean(active_posts[0]['customer_id'])
        else:
            ledger_cid = partner_cid
        eut = end_user_type(ledger_cid)
        std = std_rate[eut]
        exc = active_exception(deal_key)
        policy_rate = Decimal(clean(exc['approved_rate_pct'])) if exc else std
        commissionable = policy_rate > 0
        matched = True
        net = net_june_revenue(deal_key)
        if cosell_valid:
            share = shares.get(partner.lower(), Decimal(0))
            compare = share * net / Decimal(100)
        else:
            compare = net
        if commissionable:
            tol = abs(rev) * Decimal('0.01')
            if abs(compare - rev) > tol:
                matched = False
        if not matched:
            finding = 'UNMATCHED_TO_LEDGER'
        elif reported_rate != policy_rate:
            finding = 'RATE_MISMATCH'
        else:
            finding = None

    if finding:
        findings.append((lid, deal, partner, finding))
    else:
        # off standard but compliant
        active_posts = active_june_postings(deal_key)
        ledger_cid = clean(active_posts[0]['customer_id']) if active_posts else partner_cid
        eut = end_user_type(ledger_cid)
        std = std_rate[eut]
        exc = active_exception(deal_key)
        policy_rate = Decimal(clean(exc['approved_rate_pct'])) if exc else std
        if exc and reported_rate == policy_rate and reported_rate != std:
            compliant_off_standard.append((lid, deal, exc['exception_code'], std, policy_rate))
        # odd evidence notes
        posts = ledger_by_deal.get(deal_key, [])
        # repeated posting_id
        dups = [clean(p['posting_id']) for p in posts if p.get('_dup_posting')]
        if dups:
            odd_compliant.append((lid, deal, 'repeated_posting', dups))
        # reversal with/without reposting
        rev_pids = [clean(p['posting_id']) for p in posts if clean(p['posting_id']) in reversal_of]
        repost_pids = []
        for p in posts:
            if clean(p['posting_id']) in reversed_postings and clean(p['posting_id']) not in reversal_of and 're-posted' in p['memo'].lower():
                repost_pids.append(clean(p['posting_id']))
        if rev_pids:
            odd_compliant.append((lid, deal, 'reversal', rev_pids, repost_pids))
        # outside June posting
        outside = [clean(p['posting_id']) for p in posts if not is_june(parse_date(p['posting_date']))]
        if outside:
            odd_compliant.append((lid, deal, 'outside_june', outside))
        # net revenue differs within tolerance
        net = net_june_revenue(deal_key)
        if cosell_valid:
            share = shares.get(partner.lower(), Decimal(0))
            compare = share * net / Decimal(100)
        else:
            compare = net
        if commissionable and compare != rev and abs(compare - rev) <= abs(rev)*Decimal('0.01'):
            odd_compliant.append((lid, deal, 'net_within_tolerance', [deal]))
        # ledger customer differs from partner
        if active_posts:
            if clean(active_posts[0]['customer_id']).lower() != partner_cid.lower():
                odd_compliant.append((lid, deal, 'ledger_customer_differs', [deal]))
        # registered co-sell split
        if cosell_valid:
            odd_compliant.append((lid, deal, 'cosell_split', [deal]))
        # partner end-user type differs from master
        master_type = end_user_type(ledger_cid)
        if clean(r['partner_customer_type']).lower() != master_type.lower():
            odd_compliant.append((lid, deal, 'partner_type_differs', [deal]))
        # non-commissionable no June posting
        if not commissionable:
            june_posts = [p for p in posts if is_june(parse_date(p['posting_date'])) and clean(p['posting_id']) not in reversed_postings]
            if not june_posts:
