            odd.append({'line_id': lid, 'deal_id': deal, 'type': 'ledger_customer_differs', 'ids': [deal]})
        if cosell:
            odd.append({'line_id': lid, 'deal_id': deal, 'type': 'cosell_split', 'ids': [deal]})
        if clean(r['partner_customer_type']).lower() != eut.lower():
            odd.append({'line_id': lid, 'deal_id': deal, 'type': 'partner_type_differs', 'ids': [deal]})
        if not commissionable:
            june_active = [p for p in posts if is_june(parse_date(p['posting_date'])) and p['_pid'] not in reversed_postings]
            if not june_active:
                odd.append({'line_id': lid, 'deal_id': deal, 'type': 'noncommissionable_no_june', 'ids': [deal]})

# Write findings CSV
with open('commission_findings.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['line_id', 'deal_id', 'source_report', 'finding_code'])
    for r in findings:
        w.writerow([r['line_id'], r['deal_id'], r['source_report'], r['finding_code']])

# Write results JSON
counts = collections.Counter(r['finding_code'] for r in findings)
results = {
    'total_lines': len(lines),
    'rate_mismatch_count': counts['RATE_MISMATCH'],
    'unmatched_to_ledger_count': counts['UNMATCHED_TO_LEDGER'],
    'duplicate_line_count': counts['DUPLICATE_LINE'],
    'compliant_lines': len(lines) - len(findings),
}
with open('results.json', 'w') as f:
    json.dump(results, f, indent=2)
    f.write('\n')

# Build memo
def rate_desc(r):
    if r['exception']:
        return f"approved rate {fmt_decimal(r['policy_rate'])}% under {r['exception']}"
    return f"standard rate {fmt_decimal(r['policy_rate'])}% for {r['eut']} customers"

memo = []
memo.append('# June 2026 commission reconciliation memo\n')
memo.append('Prepared for sign-off using COMM-POL-6, the consolidated partner line list, customer master, NetSuite June revenue extract, VP exceptions register, and co-sell register.\n')
memo.append('## Headline counts\n')
memo.append(f"- Total lines reviewed: **{results['total_lines']}** (140 export rows, deduplicated to 138 unique `line_id`s)\n")
memo.append(f"- Rate mismatches: **{results['rate_mismatch_count']}**\n")
memo.append(f"- Unmatched to ledger: **{results['unmatched_to_ledger_count']}**\n")
memo.append(f"- Duplicate lines: **{results['duplicate_line_count']}**\n")
memo.append(f"- Compliant lines: **{results['compliant_lines']}**\n")
memo.append(f"- Total flagged lines: **{len(findings)}**\n")

memo.append('## Flagged lines\n')
memo.append('Policy precedence is DUPLICATE_LINE, then UNMATCHED_TO_LEDGER, then RATE_MISMATCH.\n')

# Duplicate section
dups = [r for r in findings if r['finding_code'] == 'DUPLICATE_LINE']
if dups:
    memo.append('### DUPLICATE_LINE\n')
    memo.append('A deal may be claimed once unless an active registered co-sell exists with exactly the named partners and shares summing to 100.\n')
    for r in dups:
        if r['deal_id'].lower() == 'deal-006':
            reason = 'the co-sell register rows for DEAL-006 are proposed, not active'
        elif r['deal_id'].lower() == 'deal-014':
            reason = 'the same deal appears as DEAL-014 and deal-014; identifiers are case-insensitive and no co-sell exception exists'
        elif r['deal_id'].lower() == 'deal-025':
            reason = 'the register names PartnerB and PartnerD, but both lines are PartnerD, so the co-sell exception does not apply'
        elif r['deal_id'].lower() == 'deal-121':
            reason = 'there is no active co-sell register entry for DEAL-121'
        elif r['deal_id'].lower() == 'deal-128':
            reason = 'there is no active co-sell register entry for DEAL-128'
        else:
            reason = 'no active registered co-sell exception applies'
        memo.append(f"- {r['deal_id']} ({r['line_id']}, {r['source_report']}): duplicate claim for the same deal; {reason}.\n")

# Unmatched section
unmatched = [r for r in findings if r['finding_code'] == 'UNMATCHED_TO_LEDGER']
if unmatched:
    memo.append('### UNMATCHED_TO_LEDGER\n')
    memo.append('Commissionable lines must match June ledger net revenue within 1% of claimed revenue.\n')
    for r in unmatched:
        memo.append(
            f"- {r['deal_id']} ({r['line_id']}, {r['source_report']}): claimed revenue ${fmt_decimal(r['revenue'])}, but ledger net June revenue is ${fmt_decimal(r['net_june'])}; "
            f"difference exceeds the 1% tolerance. Policy rate is {fmt_decimal(r['policy_rate'])}%, so the line is commissionable and must match.\n"
        )

# Rate mismatch section
rate = [r for r in findings if r['finding_code'] == 'RATE_MISMATCH']
if rate:
    memo.append('### RATE_MISMATCH\n')
    memo.append('The reported rate must equal the policy rate: the standard rate from the ledger customer master, or an active VP override effective on 30 June 2026.\n')
    for r in rate:
        if r['exception']:
            detail = f"policy pays {fmt_decimal(r['policy_rate'])}% under {r['exception']}, but the line reported {fmt_decimal(r['reported_rate'])}%"
        else:
            detail = f"policy pays {fmt_decimal(r['policy_rate'])}% ({rate_desc(r)}), but the line reported {fmt_decimal(r['reported_rate'])}%"
        if r['ledger_cid'].lower() != r['partner_cid'].lower():
            detail += f"; the ledger customer is {r['ledger_cid']}, which overrides the partner customer {r['partner_cid']}"
        memo.append(f"- {r['deal_id']} ({r['line_id']}, {r['source_report']}): {detail}.\n")

# Off-standard compliant
memo.append('## Compliant despite off-standard rates\n')
memo.append('These lines disagree with the standard end-user mapping but are compliant because an active VP override applies on the run date.\n')
for r in off_standard:
    memo.append(f"- {r['deal_id']} ({r['line_id']}, {r['exception_code']}): standard rate would be {fmt_decimal(r['std_rate'])}%, but approved rate is {fmt_decimal(r['policy_rate'])}% and the line reported {fmt_decimal(r['reported_rate'])}%.\n")

# Odd compliant evidence
memo.append('## Compliant lines with odd evidence\n')
memo.append('These lines are not flagged, but the underlying records look wrong. Each bullet quotes the identifier that settles the case.\n')

for typ, title in [
    ('repeated_posting', 'Repeated export rows in the ledger'),
    ('reversal_or_repost', 'Reversals and re-postings'),
    ('outside_june', 'Postings dated outside June 2026'),
    ('net_within_tolerance', 'Net June revenue differs but stays within tolerance'),
    ('ledger_customer_differs', 'Ledger customer differs from partner customer'),
    ('cosell_split', 'Registered co-sell splits'),
    ('partner_type_differs', 'Partner end-user type differs from master'),
    ('noncommissionable_no_june', 'Non-commissionable lines with no June posting'),
]:
    rows = [x for x in odd if x['type'] == typ]
    if not rows:
        continue
    memo.append(f"### {title}\n")
    for x in rows:
        if typ == 'repeated_posting':
            ids = ', '.join(x['ids'])
            memo.append(f"- {x['deal_id']} ({x['line_id']}): repeated ledger export row settled by `posting_id` {ids}.\n")
        elif typ == 'reversal_or_repost':
            revs = ', '.join(x['reversals']) if x['reversals'] else 'none'
            reposts = ', '.join(x['reposts']) if x['reposts'] else 'none'
            memo.append(f"- {x['deal_id']} ({x['line_id']}): reversal `posting_id` {revs}; re-posting `posting_id` {reposts}.\n")
        elif typ == 'outside_june':
            ids = ', '.join(x['ids'])
            memo.append(f"- {x['deal_id']} ({x['line_id']}): outside-June posting settled by `posting_id` {ids}.\n")
        elif typ == 'net_within_tolerance':
            memo.append(f"- {x['deal_id']} ({x['line_id']}): net June revenue differs from claimed revenue but remains within 1%; settled by `deal_id` {x['ids'][0]}.\n")
        elif typ == 'ledger_customer_differs':
            memo.append(f"- {x['deal_id']} ({x['line_id']}): ledger customer differs from partner `customer_id`; settled by `deal_id` {x['ids'][0]}.\n")
        elif typ == 'cosell_split':
            memo.append(f"- {x['deal_id']} ({x['line_id']}): registered co-sell split applies; settled by `deal_id` {x['ids'][0]}.\n")
        elif typ == 'partner_type_differs':
            memo.append(f"- {x['deal_id']} ({x['line_id']}): partner end-user type differs from customer master; settled by `deal_id` {x['ids'][0]}.\n")
        elif typ == 'noncommissionable_no_june':
            memo.append(f"- {x['deal_id']} ({x['line_id']}): non-commissionable line with no June posting; settled by `deal_id` {x['ids'][0]}.\n")

memo.append('## Basis\n')
memo.append('Rates and amounts were read as numbers, identifiers were matched case-insensitively and trimmed, duplicate `line_id` and `posting_id` export rows were collapsed, and policy precedence was applied exactly as specified in COMM-POL-6.\n')

with open('commission_memo.md', 'w') as f:
    f.write(''.join(memo))
